var a=`1178-mexican-ceviche`;var n=`world-1178`;var t=`MX`;var r=`central-america-caribbean`;var o=4;var s=51;var c={en:`Mexican Ceviche`,ua:`Мексиканське севіче`};var l={en:`Mexican Ceviche is a dish from Mexico prepared with tilapia, lime juice, tomato, red onion. This is a home-scale version with measured ingredients in the individual steps where they are used. Fully cooked fish rather than raw Mexican ceviche; citrus does not make raw fish reliably safe.`,ua:`Мексиканське севіче, страва кухні країни Мексика, яку готують із таких продуктів: тилапія, сік лайма, помідор, червона цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Повністю термічно приготована риба замість сирого севіче; цитрус не робить сиру рибу гарантовано безпечною.`};var h=[{en:`Poach the fish until the flesh is opaque and reaches 63°C; cool quickly before dressing with lime and vegetables.`,ua:`Варіть рибу до непрозорості та температури 63°C, швидко охолодіть перед заправкою лаймом та овочами.`,t:[`poaching`],m:10,i:[[`tilapia`,680,`g`],[`water`,700,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`lime-juice`,140,`ml`],[`tomato`,300,`g`],[`red-onion`,160,`g`],[`serrano-pepper`,2,`pcs`],[`cilantro`,30,`g`]]},{en:`Refrigerate the prepared mixture for about 30 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 30 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`avocado`,2,`pcs`],[`corn-tortillas`,8,`pcs`]]}];var d={slug:a,id:n,country:`MX`,region:r,servings:4,minutes:51,title:c,text:l,steps:h};export{t as country,d as default,n as id,s as minutes,r as region,o as servings,a as slug,h as steps,l as text,c as title};